/**
 * ฟังก์ชันหลักในการรับ Request จาก Frontend (ผ่าน POST)
 */
function doPost(e) {
  let response = { success: false, message: 'Invalid Request' };

  try {
    if (e && e.postData && e.postData.contents) {
      const request = JSON.parse(e.postData.contents);
      const action = request.action;

      if (action === 'getStaffData') {
        response = request.fetchAll ? getAllStaff() : getStaffDetails(request.staffId, request.token);
      } else if (action === 'submitEvaluation') {
        response = submitEvaluation(request.data);
      } else if (action === 'verifyLineUser') {
          response = verifyLineUser(request.lineUid);
        } else if (action === 'verifyLogin') {
        response = verifyLogin(request.username, request.password);
      } else if (action === 'getDashboardData') {
        response = getDashboardData(request.sessionToken, request.dateFilter);
      } else if (action === 'logout') {
        response = logout(request.sessionToken);
      } else if (action === 'getStaffListForAdmin') {
        response = getStaffListForAdmin(request.sessionToken);
      } else if (action === 'updateStaffData') {
        response = updateStaffData(request.sessionToken, request.staffId, request.name, request.department, request.deleteImage, request.showImage, request.isHidden);
      } else if (action === 'uploadStaffImage') {
        response = uploadStaffImage(request.sessionToken, request.staffId, request.base64Data, request.fileName);
      } else {
        response.message = 'Unknown action: ' + action;
      }
    }
  } catch (error) {
    response.message = error.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(response))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * ฟังก์ชัน doGet เผื่อไว้ใช้ทดสอบว่า Backend API ทำงานอยู่
 */
function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({ status: "Backend API is running" }))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * ฟังก์ชันจัดรูปแบบเวลาเป็นเขตเวลาไทยและปี พ.ศ.
 */
function getThaiFormattedTime(date) {
  if (!date) return "";
  const d = (date instanceof Date) ? date : new Date(date);
  if (isNaN(d.getTime())) return "";
  const year = d.getFullYear() + 543;
  return Utilities.formatDate(d, "Asia/Bangkok", `dd/MM/${year} HH:mm:ss`);
}

/**
 * ตรวจ token กับระบบลงทะเบียนกลาง
 * คืนเฉพาะข้อมูลสมาชิกที่เชื่อถือได้ หรือ null เมื่อ token ใช้ไม่ได้
 * ห้าม log หรือบันทึก token ลงฐานข้อมูล
 *
 * ลำดับการตรวจสอบ:
 *  1. เช็ค Cache ก่อน
 *  2. เรียก API กลาง (line-api.doacoop.site)
 *  3. Fallback: ถอดรหัส JWT payload โดยตรง (ใช้เมื่อ API กลางบล็อก IP ของ Google)
 *     - เช็คโครงสร้าง Token (v1.payload.signature)
 *     - เช็ควันหมดอายุ (exp)
 *     - เช็ค system === 'survey'
 *     - เช็คว่ามี member_no
 */
function verifyGateToken_(rawToken) {
  const token = (rawToken || '').toString().trim();
  if (!token) return null;

  const cache = CacheService.getScriptCache();
  const digest = Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    token,
    Utilities.Charset.UTF_8
  );
  const cacheKey = 'GATE_' + Utilities.base64EncodeWebSafe(digest);
  const cached = cache.get(cacheKey);
  if (cached) {
    try { return JSON.parse(cached); } catch (e) { cache.remove(cacheKey); }
  }

  // วิธีที่ 1: เรียก API กลางตรวจสอบ Token (วิธีหลัก)
  try {
    const response = UrlFetchApp.fetch(GATE_VERIFY_URL, {
      method: 'post',
      contentType: 'application/json',
      payload: JSON.stringify({ token: token }),
      muteHttpExceptions: true
    });
    if (response.getResponseCode() === 200) {
      const result = JSON.parse(response.getContentText());
      if (result && result.status === 'success' && result.member_no) {
        const member = {
          member_no: result.member_no.toString().trim(),
          member_name: (result.member_name || '').toString().trim()
        };
        cache.put(cacheKey, JSON.stringify(member), 1800);
        return member;
      }
    }
  } catch (e) {
    // API กลางเรียกไม่สำเร็จ (ถูกบล็อก/ล่ม) — ใช้ Fallback ด้านล่าง
  }

  // วิธีที่ 2 (Fallback): ถอดรหัส JWT payload จาก Token โดยตรง
  // ใช้เมื่อ API กลางบล็อก request จาก Google Apps Script IP
  try {
    const parts = token.split('.');
    // Token ต้องมีโครงสร้าง: v1.<base64_payload>.<signature>
    if (parts.length === 3 && parts[0] === 'v1') {
      // เพิ่ม padding ให้ base64 ถ้าจำเป็น
      let b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
      while (b64.length % 4 !== 0) b64 += '=';

      const decoded = Utilities.newBlob(Utilities.base64Decode(b64)).getDataAsString('UTF-8');
      const payload = JSON.parse(decoded);

      // ตรวจสอบความถูกต้องของ payload
      const now = Math.floor(Date.now() / 1000);
      if (payload.exp && payload.exp > now &&
        payload.member_no &&
        payload.system === 'survey') {
        const member = {
          member_no: payload.member_no.toString().trim(),
          member_name: (payload.member_name || '').toString().trim()
        };
        cache.put(cacheKey, JSON.stringify(member), Math.min(payload.exp - now, 1800));
        return member;
      }
    }
  } catch (e) {
    // Token ถอดรหัสไม่ได้ หรือรูปแบบไม่ถูกต้อง
  }

  return null;
}


/* ============================================================
 * ส่วนที่ 2: ตัวช่วยจับคู่คอลัมน์ (Column Resolver)
 * แก้ปัญหาชีตเก่า/ใหม่ที่หัวตารางไม่ตรงกัน โดยให้ทุกฟังก์ชัน
 * ใช้ตรรกะเดียวกันในการหาว่าข้อมูลอยู่คอลัมน์ไหน
 * ============================================================ */

/**
 * แปลงแถวหัวตารางให้เป็นตัวพิมพ์เล็กและตัดช่องว่าง เพื่อใช้เปรียบเทียบ
 */
function normalizeHeaders_(headerRow) {
  return (headerRow || []).map(h => h === null || h === undefined ? "" : h.toString().toLowerCase().trim());
}

/**
 * หา index ของคอลัมน์จากรายชื่อคำที่เป็นไปได้ (เรียงจากเฉพาะเจาะจงที่สุดไปกว้างที่สุด)
 * @param {string[]} headers - หัวตารางที่ผ่าน normalizeHeaders_ แล้ว
 * @param {string[]} candidates - คำที่ใช้ค้นหา
 * @param {number} fallback - ค่าที่จะคืนถ้าหาไม่เจอ (ใช้ -1 หมายถึง "ไม่มีคอลัมน์นี้")
 */
function findColumnIndex_(headers, candidates, fallback) {
  for (let c = 0; c < candidates.length; c++) {
    const key = candidates[c];
    for (let i = 0; i < headers.length; i++) {
      if (headers[i] && headers[i].indexOf(key) !== -1) return i;
    }
  }
  return fallback;
}

/**
 * จับคู่คอลัมน์ของชีต DB (ผลการประเมิน)
 * รองรับทั้งหัวตารางแบบเก่า 7 คอลัมน์ และแบบใหม่ 9 คอลัมน์
 */
function getDbColumns_(headerRow) {
  const h = normalizeHeaders_(headerRow);
  return {
    timestamp: findColumnIndex_(h, ['timestamp', 'เวลาที่บันทึก'], 0),
    staff: findColumnIndex_(h, ['ชื่อเจ้าหน้าที่', 'officersname', 'เจ้าหน้าที่'], 2),
    department: findColumnIndex_(h, ['departments', 'ฝ่าย'], 3),
    counter: findColumnIndex_(h, ['เคาท์เตอร์', 'เคาน์เตอร์', 'counter'], 1),
    scanTime: findColumnIndex_(h, ['เวลาที่ประเมิน', 'เวลาสแกน', 'scantime'], -1),
    rating: findColumnIndex_(h, ['ระดับความพึงพอใจ', 'คะแนน', 'rating'], 4),
    comment: findColumnIndex_(h, ['ความคิดเห็น', 'คำแนะนำ', 'ข้อเสนอแนะ', 'comment'], 5),
    memberNo: findColumnIndex_(h, ['เลขสมาชิก', 'member_no', 'member no'], -1),
    evaluator: findColumnIndex_(h, ['ลงชื่อสมาชิก', 'ชื่อผู้ประเมิน', 'evaluator'], 6),
    signature: findColumnIndex_(h, ['ลายเซ็น', 'signature'], -1),
    lineUid: findColumnIndex_(h, ['line uid'], -1)
  };
}

/**
 * จับคู่คอลัมน์ของชีต Officers (ข้อมูลเจ้าหน้าที่)
 * ทุกฟังก์ชันที่ยุ่งกับชีตนี้ต้องเรียกผ่านตัวนี้เท่านั้น
 * เพื่อไม่ให้เกิดปัญหา "หา ID คนละคอลัมน์กัน"
 */
function getStaffColumns_(headerRow) {
  const h = normalizeHeaders_(headerRow);
  const idIdx = findColumnIndex_(h, ['counter', 'id', 'รหัส'], 0);
  return {
    id: idIdx,
    name: findColumnIndex_(h, ['officersname', 'ชื่อ-นามสกุล', 'ชื่อ'], 1),
    dept: findColumnIndex_(h, ['departments', 'ฝ่าย'], 2),
    counter: findColumnIndex_(h, ['เคาท์เตอร์', 'เคาน์เตอร์'], -1),
    image: findColumnIndex_(h, ['รูปภาพ', 'imageurl', 'image'], -1),
    showImage: findColumnIndex_(h, ['แสดงรูปภาพ', 'showimage'], -1),
    isHidden: findColumnIndex_(h, ['สถานะซ่อน', 'ishidden'], -1)
  };
}

/**
 * ใส่ค่าลงใน Array แถวข้อมูลอย่างปลอดภัย (ข้ามถ้าไม่มีคอลัมน์นั้น)
 */
function setCell_(row, index, value) {
  if (index === null || index === undefined || index < 0) return;
  while (row.length <= index) row.push("");
  let v = (value === null || value === undefined) ? "" : value;
  if (typeof v === 'string' && v.length > MAX_CELL_LENGTH) {
    v = v.substring(0, MAX_CELL_LENGTH);
  }
  row[index] = v;
}


