/**
 * บันทึกประวัติการใช้งานระบบ (Audit Logs)
 * @param {string} userId - ไอดีของผู้ใช้งาน (UID หรือ Username)
 * @param {string} name - ชื่อของผู้ใช้งาน
 * @param {string} action - การกระทำ (เช่น Access Evaluation, Access Dashboard)
 * @param {string} details - รายละเอียดเพิ่มเติม
 * @param {string} status - สถานะ (SUCCESS, FAILED)
 */
function logAudit_(userId, name, action, details, status) {
  try {
    const sheet = getOrCreateAuditSheet_();
    const timestamp = "'" + getThaiFormattedTime(new Date());
    sheet.appendRow([timestamp, userId || "-", name || "Unknown", action || "-", details || "-", status || "-"]);
  } catch (e) {
    console.error("Failed to log audit:", e);
  }
}

/* ============================================================
 * ส่วนที่ 4: ฟังก์ชันจัดการการลงชื่อเข้าใช้ (Login) ของสมาชิก (LIFF)
 * ============================================================ */
function verifyLineUser(lineUid) {
  const lock = LockService.getScriptLock();
  try {
    const uid = (lineUid || '').toString().trim();
    if (!uid) {
      logAudit_("Unknown", "Unknown", "Access Evaluation", "ไม่พบข้อมูล LINE UID", "FAILED");
      return { success: false, message: 'ไม่พบข้อมูล LINE UID' };
    }

    lock.waitLock(5000);

    // 0. ตรวจสอบจากชีต db_login ของระบบประเมินเองก่อน (ที่มีการ importrange มา)
    const localSS = SpreadsheetApp.openById(SPREADSHEET_ID);
    const localLoginSheet = localSS.getSheetByName(LOGIN_SHEET_NAME);
    if (localLoginSheet) {
      const localData = localLoginSheet.getDataRange().getValues();
      for (let i = 0; i < localData.length; i++) {
        if (localData[i][0] && localData[i][0].toString().trim() === uid) {
          const memberName = (localData[i][4] || '') + ' ' + (localData[i][5] || '');
          logAudit_(uid, memberName, "Access Evaluation", "เข้าสู่หน้าจอประเมินสำเร็จ (Found in local db_login)", "SUCCESS");
          return {
            success: true,
            memberData: { id: localData[i][2] || uid, name: memberName, phone: localData[i][7] || '' }
          };
        }
      }
    }

    // เปลี่ยนไปใช้ฐานข้อมูลของระบบ App Portal (ระบบลงทะเบียนกลาง)
    const appPortalSS = SpreadsheetApp.openById('1Qtu-oqWyOFTbJl7D8fqj8vMBQIFOgSASTqtqNINxA94');

    // 1. เช็คชีต lineuserid ก่อน (พนักงานหลัก)
    const dbSheet = appPortalSS.getSheetByName('lineuserid');
    if (dbSheet) {
      const dbData = dbSheet.getDataRange().getValues();
      for (let i = 0; i < dbData.length; i++) {
        if (dbData[i][0] && dbData[i][0].toString().trim() === uid) {
          const memberName = (dbData[i][4] || '') + ' ' + (dbData[i][5] || '');
          logAudit_(uid, memberName, "Access Evaluation", "เข้าสู่หน้าจอประเมินสำเร็จ (Found in App Portal lineuserid)", "SUCCESS");
          return {
            success: true,
            memberData: { id: dbData[i][2] || uid, name: memberName, phone: dbData[i][7] || '' }
          };
        }
      }
    }

    // 2. ถ้าไม่เจอ เช็คชีต Login (รออนุมัติ / สำรอง)
    const loginSheet = appPortalSS.getSheetByName('Login');
    if (loginSheet) {
      const loginData = loginSheet.getDataRange().getValues();
      for (let i = 0; i < loginData.length; i++) {
        if (loginData[i][0] && loginData[i][0].toString().trim() === uid) {
          const memberName = (loginData[i][3] || '') + ' ' + (loginData[i][4] || '');
          logAudit_(uid, memberName, "Access Evaluation", "เข้าสู่หน้าจอประเมินสำเร็จ (Found in App Portal Login)", "SUCCESS");
          return {
            success: true,
            memberData: { id: loginData[i][2] || uid, name: memberName, phone: loginData[i][6] || '' }
          };
        }
      }
    }

    logAudit_(uid, "Unknown", "Access Evaluation", "เข้าใช้งานล้มเหลว (ไม่พบข้อมูลในระบบลงทะเบียน)", "FAILED");
    return { success: false, message: 'ยังไม่ได้ลงทะเบียน' };
  } catch (err) {
    logAudit_("Unknown", "System", "Access Evaluation Error", err.toString(), "ERROR");
    return { success: false, message: err.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

function registerLineUser(lineUid, name, phone) {
  const lock = LockService.getScriptLock();
  try {
    const uid = (lineUid || '').toString().trim();
    const userName = (name || '').toString().trim();
    const userPhone = (phone || '').toString().trim();

    if (!uid) return { success: false, message: 'ไม่พบข้อมูล LINE UID' };
    if (!userName) return { success: false, message: 'กรุณากรอกชื่อ-นามสกุล' };
    if (!userPhone) return { success: false, message: 'กรุณากรอกเบอร์โทรศัพท์' };

    lock.waitLock(10000);
    const sheet = getOrCreateMemberLoginSheet_();
    const data = sheet.getDataRange().getValues();

    // เช็คอีกรอบว่าลงทะเบียนไปแล้วหรือยัง
    for (let i = 1; i < data.length; i++) {
      if (data[i][1] && data[i][1].toString().trim() === uid) {
        return { success: true, message: 'ท่านได้ลงทะเบียนเรียบร้อยแล้ว' };
      }
    }

    // สร้าง ID ใหม่
    const newId = 'M' + ('0000' + data.length).slice(-5);
    const now = getThaiFormattedTime(new Date());

    sheet.appendRow([newId, uid, userName, userPhone, now]);

    return {
      success: true,
      message: 'ลงทะเบียนสำเร็จ',
      memberData: {
        id: newId,
        name: userName,
        phone: userPhone
      }
    };
  } catch (err) {
    return { success: false, message: err.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

/* ============================================================
 * ส่วนที่ 5: ฟังก์ชันจัดการข้อมูล (Data Handlers)
 * ============================================================ */

/**
 * รับข้อมูลจากฟอร์มประเมินและบันทึกลงชีต DB
 * เขียนข้อมูลโดยอ้างอิงตำแหน่งจากหัวตารางจริง ไม่ใช้ลำดับตายตัว
 * @param {Object} formData - ข้อมูลจากฟอร์ม
 */
function submitEvaluation(formData) {
  const lock = LockService.getScriptLock();
  let member = null;
  try {
    const data = formData || {};

    // ตรวจจากระบบกลางก่อนเสมอ เพราะ Web App URL ถูกเรียกตรงได้
    if (data.isAdmin) {
      member = { member_no: 'ADMIN_TEST', member_name: 'Admin Simulator' };
    } else {
      member = verifyGateToken_(data.token);
    }
    if (!member) {
      return { success: false, message: 'กรุณาเปิดลิงก์แบบประเมินจากแอป LINE อีกครั้ง' };
    }

    // ตรวจสอบความถูกต้องของคะแนนก่อนบันทึก
    const rating = parseInt(data.rating, 10);
    if (!(rating >= 1 && rating <= 3)) {
      return { success: false, message: "ระดับความพึงพอใจไม่ถูกต้อง กรุณาเลือกใหม่อีกครั้ง" };
    }
    if (!data.staffName || data.staffName.toString().trim() === "") {
      return { success: false, message: "ไม่พบข้อมูลเจ้าหน้าที่ที่ต้องการประเมิน" };
    }

    // ป้องกันการเขียนข้อมูลพร้อมกัน (Race Condition)
    lock.waitLock(10000);

    const sheet = getOrCreateDbSheet_();
    let lastCol = Math.max(sheet.getLastColumn(), 1);
    let headerRow = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
    let col = getDbColumns_(headerRow);

    // ชีตเดิมอาจยังไม่มีเลขสมาชิก จึงเพิ่มต่อท้ายโดยไม่ย้ายข้อมูลเก่า
    if (col.memberNo < 0) {
      sheet.getRange(1, lastCol + 1).setValue('เลขสมาชิก').setFontWeight('bold').setBackground('#f3f4f6');
      lastCol = sheet.getLastColumn();
      headerRow = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
      col = getDbColumns_(headerRow);
    }

    const now = new Date();
    const row = new Array(lastCol).fill("");

    setCell_(row, col.timestamp, "'" + getThaiFormattedTime(now));
    setCell_(row, col.staff, data.staffName.toString().trim());
    setCell_(row, col.department, (data.department || "").toString().trim());
    setCell_(row, col.counter, (data.counter || "").toString().trim());

    let scanTimeVal = data.scanTime ? data.scanTime.toString() : getThaiFormattedTime(now);
    if (!scanTimeVal.startsWith("'")) scanTimeVal = "'" + scanTimeVal;
    setCell_(row, col.scanTime, scanTimeVal);
    setCell_(row, col.rating, rating);
    setCell_(row, col.comment, (data.comment || "").toString().trim());

    // ใช้ข้อมูลจาก API กลางเท่านั้น ไม่เชื่อชื่อหรือรหัสที่ browser ส่งมา
    const evaluatorName = member.member_name || 'สมาชิกเลขที่ ' + member.member_no;
    setCell_(row, col.memberNo, member.member_no);
    setCell_(row, col.evaluator, evaluatorName);
    setCell_(row, col.signature, (data.signatureBase64 || "").toString());

    sheet.appendRow(row);
    logAudit_(member.member_no, evaluatorName, "Submit Evaluation", `ประเมินเจ้าหน้าที่: ${data.staffName} (คะแนน: ${rating})`, "SUCCESS");
    return { success: true, message: "บันทึกข้อมูลเรียบร้อยแล้ว" };
  } catch (error) {
    logAudit_(member ? member.member_no : 'Unknown', "System", "Submit Evaluation Error", error.toString(), "ERROR");
    return { success: false, message: error.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

/**
 * ดึงข้อมูลเจ้าหน้าที่รายบุคคลจากชีต Officers
 * @param {string} staffId - ID ของเจ้าหน้าที่ที่ต้องการ
 * @param {string} token - Gate token เพื่อ pre-verify ตั้งแต่ตอนโหลดหน้า
 */
function getStaffDetails(staffId, token) {
  if (!staffId) return null;
  
  if (token) {
    const member = verifyGateToken_(token);
    if (member && member.member_no) {
      // Check if this member_no is registered in the DB
      const verifyResult = verifyLineUser(member.member_no);
      if (!verifyResult.success) {
        return { requireRegistration: true };
      }
    }
  }

  const key = staffId.toString().trim();
  const allStaff = getAllStaff().staffList;
  return allStaff.find(staff => staff.id === key) || null;
}

/**
 * ดึงข้อมูลเจ้าหน้าที่ทั้งหมด พร้อม URL ของ Web App สำหรับสร้าง QR Code
 */
function getAllStaff() {
  const sheet = getOrCreateStaffSheet_();
  const data = sheet.getDataRange().getValues();
  const staffList = [];

  if (data.length > 1) {
    const col = getStaffColumns_(data[0]);

    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const idVal = (col.id >= 0 && row[col.id] !== undefined && row[col.id] !== null)
        ? row[col.id].toString().trim() : "";
      if (!idVal) continue;

      // ข้อความเคาท์เตอร์: ใช้จากคอลัมน์เฉพาะถ้ามี ถ้าไม่มีก็เติมคำนำหน้าให้เอง
      let counterDisplay = "";
      if (col.counter >= 0 && col.counter !== col.id && row[col.counter]) {
        counterDisplay = row[col.counter].toString().trim();
      }
      if (!counterDisplay) {
        counterDisplay = (!isNaN(idVal) || idVal.length <= 2) ? "เคาท์เตอร์ที่ " + idVal : idVal;
      }

      staffList.push({
        id: idVal,
        name: (col.name >= 0 && row[col.name]) ? row[col.name].toString().trim() : "",
        department: (col.dept >= 0 && row[col.dept]) ? row[col.dept].toString().trim() : "",
        counter: counterDisplay,
        imageUrl: (col.image >= 0 && row[col.image]) ? row[col.image].toString().trim() : "",
        showImage: (col.showImage >= 0 && row[col.showImage] !== undefined && row[col.showImage] !== null && row[col.showImage] !== '') ? (row[col.showImage] !== false && row[col.showImage].toString().toUpperCase() !== 'FALSE' && row[col.showImage] !== 'ไม่แสดง') : true,
        isHidden: (col.isHidden >= 0 && row[col.isHidden] !== undefined && row[col.isHidden] !== null && row[col.isHidden] !== '') ? (row[col.isHidden] === true || row[col.isHidden].toString().toUpperCase() === 'TRUE' || row[col.isHidden] === 'ซ่อน') : false
      });
    }
  }

  // ดึง URL ของ Web App ที่ Deploy แล้ว
  let webAppUrl = "";
  try {
    webAppUrl = ScriptApp.getService().getUrl() || "";
  } catch (e) {
    webAppUrl = "";
  }

  return { staffList, webAppUrl };
}


/* ============================================================
 * ส่วนที่ 6: ระบบยืนยันตัวตนผู้ดูแล (Dashboard Authentication)
 * ============================================================ */

/**
 * แปลงรหัสผ่านเป็น SHA-256 (hex) สำหรับเก็บลงชีตแบบไม่เปิดเผยรหัสจริง
 * เรียกฟังก์ชันนี้จาก Editor เพื่อสร้างค่า hash ไปวางแทนรหัสผ่านเปล่าในชีต db_login
 */
function hashPassword(plainText) {
  const bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, plainText.toString(), Utilities.Charset.UTF_8);
  return bytes.map(b => ('0' + (b & 0xFF).toString(16)).slice(-2)).join('');
}

/**
 * เทียบรหัสผ่าน รองรับทั้งแบบเก็บเป็นข้อความเปล่า (ของเดิม)
 * และแบบเก็บเป็น SHA-256 hex 64 ตัวอักษร (แนะนำ)
 */
function passwordMatches_(inputPassword, storedPassword) {
  const stored = (storedPassword || "").toString().trim();
  const input = (inputPassword || "").toString().trim();
  if (!stored) return false;
  if (/^[0-9a-f]{64}$/i.test(stored)) {
    return hashPassword(input).toLowerCase() === stored.toLowerCase();
  }
  return input === stored;
}

/**
 * สร้าง Session ใหม่และคืนค่า Token
 */
function createSession_(user) {
  const token = Utilities.getUuid().replace(/-/g, '') + Date.now().toString(36);
  const props = PropertiesService.getScriptProperties();
  props.setProperty(SESSION_PREFIX + token, JSON.stringify({
    name: user.name,
    role: user.role,
    department: user.department,
    exp: Date.now() + SESSION_TTL_MS
  }));
  cleanupExpiredSessions_();
  return token;
}

/**
 * อ่าน Session จาก Token คืน null ถ้าไม่มีหรือหมดอายุ
 */
function getSession_(token) {
  if (!token) return null;
  const props = PropertiesService.getScriptProperties();
  const raw = props.getProperty(SESSION_PREFIX + token.toString());
  if (!raw) return null;
  try {
    const session = JSON.parse(raw);
    // ปิดการตรวจสอบหมดอายุ เพื่อให้ Session อยู่ตลอดไป
    // if (!session.exp || session.exp < Date.now()) {
    //   props.deleteProperty(SESSION_PREFIX + token.toString());
    //   return null;
    // }
    return session;
  } catch (e) {
    return null;
  }
}

/**
 * ลบ Session ที่หมดอายุออกจาก Script Properties
 */
function cleanupExpiredSessions_() {
  try {
    const props = PropertiesService.getScriptProperties();
    const all = props.getProperties();
    const now = Date.now();
    Object.keys(all).forEach(function (key) {
      if (key.indexOf(SESSION_PREFIX) !== 0) return;
      try {
        const session = JSON.parse(all[key]);
        // ปิดการลบ Session หมดอายุ (Session ไม่หมดอายุ)
        // if (!session.exp || session.exp < now) props.deleteProperty(key);
      } catch (e) {
        props.deleteProperty(key);
      }
    });
  } catch (e) { }
}

/**
 * ตรวจสอบสิทธิ์ก่อนเข้าถึงข้อมูล
 * @param {string} token - Token จากหน้าเว็บ
 * @param {boolean} requireItDept - ต้องเป็นฝ่ายสารสนเทศเท่านั้นหรือไม่
 */
function requireSession_(token, requireItDept) {
  const session = getSession_(token);
  if (!session) {
    return { ok: false, response: { success: false, authRequired: true, message: 'เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่' } };
  }
  if (requireItDept && (!session.department || session.department.indexOf('สารสนเทศ') === -1)) {
    return { ok: false, response: { success: false, message: 'คุณไม่มีสิทธิ์ใช้งานส่วนนี้ (เฉพาะฝ่ายสารสนเทศ)' } };
  }
  return { ok: true, session: session };
}

/**
 * ตรวจสอบการล็อกอินเข้าสู่ระบบ Dashboard
 */
function verifyLogin(username, password) {
  try {
    const user = (username || '').toString().trim();
    const pass = (password || '').toString();

    if (!user || !pass) {
      return { success: false, message: 'กรุณากรอกชื่อผู้ใช้งานและรหัสผ่าน' };
    }

    // จำกัดจำนวนครั้งที่ล็อกอินผิด ป้องกันการสุ่มเดารหัสผ่าน
    const cache = CacheService.getScriptCache();
    const attemptKey = 'LOGIN_FAIL_' + user.toLowerCase();
    const attempts = parseInt(cache.get(attemptKey) || '0', 10);
    if (attempts >= LOGIN_MAX_ATTEMPTS) {
      return { success: false, message: 'ล็อกอินผิดเกินกำหนด กรุณารอ 15 นาทีแล้วลองใหม่' };
    }

    const sheet = SpreadsheetApp.openById(SPREADSHEET_ID).getSheetByName(LOGIN_SHEET_NAME);
    if (!sheet) {
      return { success: false, message: 'ไม่พบฐานข้อมูลผู้ใช้งาน (db_login) กรุณาสร้างชีต db_login ก่อน' };
    }

    const data = sheet.getDataRange().getValues();
    // หัวคอลัมน์: userID(0) | Displayname(1) | username(2) | pictureUrl(3) | name(4) | surname(5)
    //             status(6) | phone(7) | Timestamp(8) | password(9) | ฝ่าย(10) | App Access(11) | positions(12)
    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const dbUsername = String(row[2] || '').trim();
      if (dbUsername !== user) continue;
      if (!passwordMatches_(pass, row[9])) continue;

      const dbStatus = String(row[6] || '').trim().toLowerCase();
      if (dbStatus !== 'active') {
        logAudit_(user, String(row[4] || ''), "Access Dashboard", "เข้าสู่ระบบล้มเหลว (บัญชีถูกระงับ)", "FAILED");
        return { success: false, message: 'บัญชีนี้ถูกระงับการใช้งานชั่วคราว' };
      }

      const userDept = String(row[10] || '').trim();
      const userRole = String(row[12] || '').trim();

      // ตรวจสอบสิทธิ์การเข้าถึงหน้า Dashboard
      const allowedKeywords = ['สารสนเทศ', 'ผู้ช่วยผู้จัดการ', 'ผู้จัดการ'];
      const isAllowed = allowedKeywords.some(keyword => userDept.includes(keyword) || userRole.includes(keyword));

      if (!isAllowed) {
        logAudit_(user, String(row[4] || ''), "Access Dashboard", "เข้าสู่ระบบล้มเหลว (ไม่มีสิทธิ์เข้าถึง)", "FAILED");
        return { success: false, message: 'ไม่มีสิทธิ์เข้าถึง: สงวนสิทธิ์เฉพาะฝ่ายสารสนเทศ ผู้ช่วยผู้จัดการ หรือผู้จัดการเท่านั้น' };
      }

      const profile = {
        name: (String(row[4] || '') + ' ' + String(row[5] || '')).trim() || String(row[1] || ''),
        role: String(row[12] || ''),
        department: String(row[10] || '').trim()
      };

      const token = createSession_(profile);
      const dashboardRes = getDashboardData(token, 'all');

      cache.remove(attemptKey);
      logAudit_(user, profile.name, "Access Dashboard", "เข้าสู่ระบบ Dashboard สำเร็จ", "SUCCESS");

      return {
        success: true,
        token: token,
        name: profile.name,
        role: profile.role,
        department: profile.department,
        isItAdmin: profile.department.indexOf('สารสนเทศ') !== -1,
        initialDashboardData: dashboardRes
      };
    }

    cache.put(attemptKey, (attempts + 1).toString(), LOGIN_LOCK_SECONDS);
    logAudit_(user, "Unknown", "Access Dashboard", "เข้าสู่ระบบล้มเหลว (ชื่อหรือรหัสผ่านผิด)", "FAILED");
    return { success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' };
  } catch (err) {
    logAudit_("Unknown", "System", "Access Dashboard Error", err.toString(), "ERROR");
    return { success: false, message: 'Backend Error: ' + err.toString() };
  }
}

/**
 * ออกจากระบบ (ทำลาย Session ฝั่งเซิร์ฟเวอร์)
 */
function logout(token) {
  try {
    if (token) PropertiesService.getScriptProperties().deleteProperty(SESSION_PREFIX + token.toString());
  } catch (e) { }
  return { success: true };
}


/* ============================================================
 * ส่วนที่ 6: API สำหรับผู้ดูแลระบบ (ต้องมี Token)
 * ============================================================ */

/**
 * ดึงข้อมูลสรุปสำหรับหน้า Dashboard
 * @param {string} token - Token ที่ได้จาก verifyLogin
 */
function getDashboardData(token, dateFilter) {
  const auth = requireSession_(token, false);
  if (!auth.ok) return auth.response;

  if (!dateFilter) dateFilter = 'all';
  const now = new Date();
  const yearBE = now.getFullYear() + 543;
  const todayBEStr = Utilities.formatDate(now, "Asia/Bangkok", "dd/MM/") + yearBE;
  const monthBEStr = Utilities.formatDate(now, "Asia/Bangkok", "MM/") + yearBE;

  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const sheet = ss.getSheetByName(DB_SHEET_NAME);
  const counts = { '3': 0, '2': 0, '1': 0 };
  const staffData = {};
  const trendMap = {}; // { 'dd/MM/yyyy': { excellent: 0, good: 0, poor: 0 } }
  let total = 0;

  // โหลดรายชื่อเจ้าหน้าที่ทั้งหมดมาก่อน เพื่อให้แสดงครบทุกคนแม้ยังไม่มีคนประเมิน
  try {
    const allStaff = getAllStaff().staffList || [];
    allStaff
      .filter(staff => staff.name)
      .sort((a, b) => a.name.toString().localeCompare(b.name.toString(), 'th', { numeric: true, sensitivity: 'base' }))
      .forEach(staff => {
        staffData[staff.name.trim()] = { excellent: 0, good: 0, poor: 0, comments: [], imageUrl: staff.imageUrl || "", counter: staff.counter || "", id: staff.id || "", isHidden: staff.isHidden || false };
      });
  } catch (e) { }

  if (!sheet) {
    return { success: false, message: 'ไม่พบชีตฐานข้อมูล (' + DB_SHEET_NAME + ')' };
  }

  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) {
    return { success: true, counts: counts, total: total, staffData: staffData };
  }

  const col = getDbColumns_(data[0]);

  for (let i = 1; i < data.length; i++) {
    const timestamp = col.timestamp >= 0 ? data[i][col.timestamp] : "";
    let tsStr = "";
    if (timestamp) {
      if (timestamp instanceof Date) {
        const yyyy = timestamp.getFullYear();
        const finalYyyy = yyyy < 2500 ? yyyy + 543 : yyyy;
        const mm = String(timestamp.getMonth() + 1).padStart(2, '0');
        const dd = String(timestamp.getDate()).padStart(2, '0');
        tsStr = `${dd}/${mm}/${finalYyyy} 00:00:00`;
      } else {
        tsStr = timestamp.toString().trim();
      }

      if (dateFilter !== 'all') {
        if (dateFilter === 'today') {
          if (!tsStr.startsWith(todayBEStr)) continue;
        } else if (dateFilter === 'this_month') {
          if (tsStr.substring(3, 10) !== monthBEStr) continue;
        } else if (dateFilter !== 'all') {
          if (dateFilter.indexOf('_') !== -1) {
            const rangeParts = dateFilter.split('_');
            if (rangeParts.length === 2) {
              const startNum = parseInt(rangeParts[0].replace(/-/g, ''), 10);
              const endNum = parseInt(rangeParts[1].replace(/-/g, ''), 10);
              const dd = tsStr.substring(0, 2);
              const mm = tsStr.substring(3, 5);
              const yyyyBE = tsStr.substring(6, 10);
              if (dd && mm && yyyyBE) {
                const yyyy = parseInt(yyyyBE, 10) - 543;
                const tsNum = parseInt(yyyy.toString() + mm + dd, 10);
                if (tsNum < startNum || tsNum > endNum) continue;
              }
            }
          } else {
            // สมมติว่าเป็นรูปแบบ YYYY-MM-DD แบบวันเดียว
            const parts = dateFilter.split('-');
            if (parts.length === 3) {
              const targetBEStr = parts[2] + '/' + parts[1] + '/' + (parseInt(parts[0], 10) + 543);
              if (!tsStr.startsWith(targetBEStr)) continue;
            }
          }
        }
      }
    }

    const rating = parseInt(data[i][col.rating], 10);
    if (!(rating >= 1 && rating <= 3)) continue;

    counts[rating]++;
    total++;

    // Accumulate trend data
    const dateOnly = tsStr ? tsStr.substring(0, 10) : 'Unknown';
    if (!trendMap[dateOnly]) {
      trendMap[dateOnly] = { excellent: 0, good: 0, poor: 0, staff: {} };
    }
    if (rating === 3) trendMap[dateOnly].excellent++;
    else if (rating === 2) trendMap[dateOnly].good++;
    else trendMap[dateOnly].poor++;

    const rawName = col.staff >= 0 ? data[i][col.staff] : "";
    if (!rawName || rawName.toString().trim() === "") continue;

    const name = rawName.toString().trim();
    if (!trendMap[dateOnly].staff[name]) {
      trendMap[dateOnly].staff[name] = { excellent: 0, good: 0, poor: 0 };
    }
    if (rating === 3) trendMap[dateOnly].staff[name].excellent++;
    else if (rating === 2) trendMap[dateOnly].staff[name].good++;
    else trendMap[dateOnly].staff[name].poor++;

    if (!staffData[name]) {
      staffData[name] = { excellent: 0, good: 0, poor: 0, comments: [], imageUrl: "", counter: "", id: "999" };
    }
    if (rating === 3) staffData[name].excellent++;
    else if (rating === 2) staffData[name].good++;
    else staffData[name].poor++;

    const comment = col.comment >= 0 ? data[i][col.comment] : "";
    if (comment && comment.toString().trim() !== "") {
      const evaluator = col.evaluator >= 0 ? data[i][col.evaluator] : "";

      // Sentiment Analysis (Simple Rules)
      let sentiment = 'neutral';
      if (rating === 3) sentiment = 'positive';
      else if (rating === 1) sentiment = 'negative';

      staffData[name].comments.push({
        text: comment.toString().trim(),
        rating: rating,
        sentiment: sentiment,
        evaluator: (evaluator && evaluator.toString().trim() !== "") ? evaluator.toString().trim() : "ไม่ระบุชื่อ"
      });
    }
  }

  // Process trendMap to array for Chart.js
  const trendLabels = [];
  const trendExcellent = [];
  const trendGood = [];
  const trendPoor = [];
  const trendStaff = [];

  const sortedDates = Object.keys(trendMap).sort((a, b) => {
    if (a === 'Unknown') return -1;
    if (b === 'Unknown') return 1;
    const partsA = a.split('/');
    const partsB = b.split('/');
    if (partsA.length === 3 && partsB.length === 3) {
      const valA = parseInt(partsA[2] + partsA[1] + partsA[0], 10);
      const valB = parseInt(partsB[2] + partsB[1] + partsB[0], 10);
      return valA - valB;
    }
    return a.localeCompare(b);
  });

  sortedDates.forEach(date => {
    trendLabels.push(date);
    trendExcellent.push(trendMap[date].excellent);
    trendGood.push(trendMap[date].good);
    trendPoor.push(trendMap[date].poor);
    trendStaff.push(trendMap[date].staff);
  });

  const trendData = {
    labels: trendLabels,
    excellent: trendExcellent,
    good: trendGood,
    poor: trendPoor,
    staff: trendStaff
  };

  return { success: true, counts: counts, total: total, staffData: staffData, trendData: trendData };
}

/**
 * ดึงรายชื่อเจ้าหน้าที่สำหรับหน้าจัดการ (เฉพาะฝ่ายสารสนเทศ)
 */
function getStaffListForAdmin(token) {
  const auth = requireSession_(token, true);
  if (!auth.ok) return auth.response;
  const result = getAllStaff();
  return { success: true, staffList: result.staffList, webAppUrl: result.webAppUrl };
}

/**
 * อัปเดตข้อมูลเจ้าหน้าที่ (ชื่อ, ฝ่าย)
 */
function updateStaffData(token, staffId, name, department, deleteImage, showImage, isHidden) {
  const auth = requireSession_(token, true);
  if (!auth.ok) return auth.response;

  const lock = LockService.getScriptLock();
  try {
    const key = (staffId || '').toString().trim();
    const newName = (name || '').toString().trim();
    if (!key) return { success: false, message: 'ไม่พบรหัสเจ้าหน้าที่' };
    if (!newName) return { success: false, message: 'กรุณากรอกชื่อ-นามสกุล' };

    lock.waitLock(10000);

    const sheet = getOrCreateStaffSheet_();
    const data = sheet.getDataRange().getValues();
    const col = getStaffColumns_(data[0]);

    for (let i = 1; i < data.length; i++) {
      if (col.id < 0 || !data[i][col.id]) continue;
      if (data[i][col.id].toString().trim() !== key) continue;

      // +1 เพราะ getRange เริ่มนับที่ 1 ไม่ใช่ 0
      if (col.name >= 0) sheet.getRange(i + 1, col.name + 1).setValue(newName);
      if (col.dept >= 0) sheet.getRange(i + 1, col.dept + 1).setValue((department || '').toString().trim());

      let showImgCol = col.showImage;
      if (showImgCol < 0) {
        const lastCol = sheet.getLastColumn();
        sheet.getRange(1, lastCol + 1).setValue('แสดงรูปภาพ');
        showImgCol = lastCol;
        col.showImage = showImgCol;
      }
      sheet.getRange(i + 1, showImgCol + 1).setValue(showImage ? 'TRUE' : 'FALSE');

      let hideCol = col.isHidden;
      if (hideCol < 0) {
        const lastCol = sheet.getLastColumn();
        sheet.getRange(1, lastCol + 1).setValue('สถานะซ่อน');
        hideCol = lastCol;
        col.isHidden = hideCol;
      }
      sheet.getRange(i + 1, hideCol + 1).setValue(isHidden ? 'TRUE' : 'FALSE');

      if (deleteImage && col.image >= 0) {
        sheet.getRange(i + 1, col.image + 1).setValue('');
      }

      return { success: true, message: 'อัปเดตข้อมูลเรียบร้อยแล้ว' };
    }

    return { success: false, message: 'ไม่พบเจ้าหน้าที่ ID: ' + key };
  } catch (err) {
    return { success: false, message: 'Error: ' + err.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

/**
 * อัปโหลดรูปภาพเจ้าหน้าที่ไปยัง Google Drive แล้วบันทึก URL ลงชีต
 */
function uploadStaffImage(token, staffId, base64Data, fileName) {
  const auth = requireSession_(token, true);
  if (!auth.ok) return auth.response;

  const lock = LockService.getScriptLock();
  try {
    const key = (staffId || '').toString().trim();
    if (!key) return { success: false, message: 'ไม่พบรหัสเจ้าหน้าที่' };
    if (!base64Data) return { success: false, message: 'ไม่พบข้อมูลรูปภาพ' };

    const typeMatch = base64Data.toString().match(/^data:(image\/[a-z0-9.+-]+);base64,/i);
    if (!typeMatch) return { success: false, message: 'ไฟล์ที่เลือกไม่ใช่รูปภาพที่รองรับ' };

    lock.waitLock(15000);

    // หาหรือสร้างโฟลเดอร์ Staff_Photos
    const folders = DriveApp.getFoldersByName('Staff_Photos');
    const folder = folders.hasNext() ? folders.next() : DriveApp.createFolder('Staff_Photos');

    // แปลง base64 เป็น Blob แล้วบันทึกลง Drive
    const contentType = typeMatch[1];
    const base64Clean = base64Data.toString().replace(/^data:.*?;base64,/, '');
    const safeName = (fileName || 'photo.png').toString().replace(/[^\w.\-]/g, '_');
    const blob = Utilities.newBlob(Utilities.base64Decode(base64Clean), contentType, 'staff_' + key + '_' + safeName);

    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    const imageUrl = 'https://drive.google.com/thumbnail?id=' + file.getId() + '&sz=w400';

    // อัปเดต URL ลงชีต Officers
    const sheet = getOrCreateStaffSheet_();
    const data = sheet.getDataRange().getValues();
    const col = getStaffColumns_(data[0]);

    let imageCol = col.image;
    if (imageCol < 0) {
      // ยังไม่มีคอลัมน์รูปภาพ ให้เพิ่มต่อท้าย
      const lastCol = sheet.getLastColumn();
      sheet.getRange(1, lastCol + 1).setValue('รูปภาพ');
      imageCol = lastCol; // 0-indexed
    }

    for (let i = 1; i < data.length; i++) {
      if (col.id < 0 || !data[i][col.id]) continue;
      if (data[i][col.id].toString().trim() !== key) continue;
      sheet.getRange(i + 1, imageCol + 1).setValue(imageUrl);
      return { success: true, imageUrl: imageUrl };
    }

    return { success: false, message: 'อัปโหลดรูปแล้ว แต่ไม่พบเจ้าหน้าที่ ID: ' + key };
  } catch (err) {
    return { success: false, message: 'Upload Error: ' + err.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

/* ============================================================
 * ส่วนที่ 7: สำรองข้อมูลอัตโนมัติ (Automatic Backup)
 * ============================================================ */

const BACKUP_FOLDER_NAME = "QR_Backups"; // โฟลเดอร์ใน Google Drive ที่เก็บไฟล์สำรอง
const BACKUP_KEEP = 30;                   // เก็บไฟล์สำรองล่าสุดกี่ชุด (ที่เกินจะถูกลบ)

/**
 * สำรองสเปรดชีตทั้งไฟล์ไปเก็บใน Drive โฟลเดอร์ QR_Backups
 * ตั้งชื่อไฟล์ตามวันเวลาไทย (พ.ศ.) แล้วลบไฟล์เก่าที่เกินโควตาทิ้ง
 *
 * ฟังก์ชันนี้ถูกเรียกโดย Time-driven trigger (ดู setupDailyBackup)
 * และเรียกเองจาก Editor ก็ได้
 */
function backupDatabase() {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000);

    const folder = getOrCreateBackupFolder_();
    const now = new Date();
    const stamp = Utilities.formatDate(now, "Asia/Bangkok", "yyyy-MM-dd_HHmm");
    const beYear = now.getFullYear() + 543;
    const backupName = "Backup_ประเมิน_" + stamp + "_พ.ศ." + beYear;

    // ก๊อปปี้ทั้งไฟล์สเปรดชีต (ได้ทุกชีต: DB, Officers, db_login, db_member_login)
    DriveApp.getFileById(SPREADSHEET_ID).makeCopy(backupName, folder);

    // ลบไฟล์สำรองเก่าที่เกินโควตา
    pruneOldBackups_(folder, BACKUP_KEEP);

    return { success: true, message: "สำรองข้อมูลเรียบร้อย: " + backupName };
  } catch (err) {
    // บันทึกลง Execution log ให้ตรวจย้อนหลังได้ (ดูที่เมนู Executions ใน Apps Script)
    console.error("Backup failed: " + err.toString());
    return { success: false, message: "สำรองข้อมูลไม่สำเร็จ: " + err.toString() };
  } finally {
    try { lock.releaseLock(); } catch (e) { }
  }
}

/**
 * หาหรือสร้างโฟลเดอร์เก็บไฟล์สำรอง
 */
function getOrCreateBackupFolder_() {
  const folders = DriveApp.getFoldersByName(BACKUP_FOLDER_NAME);
  return folders.hasNext() ? folders.next() : DriveApp.createFolder(BACKUP_FOLDER_NAME);
}

/**
 * ลบไฟล์สำรองเก่าที่เกินจำนวน keep (เก็บชุดใหม่สุดไว้ ทิ้งของเก่าลงถังขยะ)
 */
function pruneOldBackups_(folder, keep) {
  const files = [];
  const it = folder.getFiles();
  while (it.hasNext()) files.push(it.next());

  // เรียงจากใหม่ไปเก่า
  files.sort(function (a, b) { return b.getDateCreated().getTime() - a.getDateCreated().getTime(); });

  for (let i = keep; i < files.length; i++) {
    files[i].setTrashed(true);
  }
}

/**
 * ตั้ง (หรือรีเซ็ต) Time-driven trigger ให้สำรองข้อมูลทุกวันตอนตี 1
 * ⚠️ ต้องเปิด Apps Script Editor แล้วกด Run ฟังก์ชันนี้ "หนึ่งครั้ง" เพื่อเริ่มระบบสำรองอัตโนมัติ
 */
function setupDailyBackup() {
  // ลบ trigger เดิมของ backupDatabase กันตั้งซ้ำ
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (t.getHandlerFunction() === 'backupDatabase') ScriptApp.deleteTrigger(t);
  });

  ScriptApp.newTrigger('backupDatabase')
    .timeBased()
    .everyDays(1)
    .atHour(1) // ตี 1 ตามเขตเวลาของโปรเจกต์ (Asia/Bangkok)
    .create();

  return 'ตั้งเวลาสำรองข้อมูลอัตโนมัติทุกวัน ตอน 01:00 น. เรียบร้อยแล้ว';
}




/**
 * ฟังก์ชันสำหรับแก้ไขข้อมูลเก่าในชีต (One-time run)
 * ให้รันฟังก์ชันนี้จากหน้าต่าง Apps Script Editor เพื่อแปลงวันที่เก่าๆ ให้เป็น string ที่มี ' นำหน้า
 */
function fixTimestamps() {
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const sheet = ss.getSheetByName(DB_SHEET_NAME);
  if (!sheet) return;

  const data = sheet.getDataRange().getValues();
  const col = getDbColumns_(data[0]);

  if (col.timestamp < 0) return;

  for (let i = 1; i < data.length; i++) {
    const val = data[i][col.timestamp];
    if (val) {
      let newVal = "";
      if (val instanceof Date) {
        newVal = "'" + getThaiFormattedTime(val);
        sheet.getRange(i + 1, col.timestamp + 1).setValue(newVal);
      } else if (typeof val === 'string' && !val.startsWith("'")) {
        // ถ้าเป็น string อยู่แล้ว แต่ไม่มี ' นำหน้า
        // แต่จริงๆ getValues() มันลบ ' ออกตอนอ่าน ให้เช็คแค่ว่ามันเป็นวันที่ปกติ
        // ให้เขียนทับแบบ Force String ด้วย setValue("'" + val)
        sheet.getRange(i + 1, col.timestamp + 1).setValue("'" + val.trim());
      }
    }
  }
}

const DOCX_BASE64_SUMMARY = "";
const DOCX_BASE64_INDIVIDUAL = "";

function generatePdfFromWordTemplate(type, payload) {
  let tempDocId = null;
  try {
    const filename = payload.filename || 'รายงาน';
    const b64Data = (type === 'summary') ? DOCX_BASE64_SUMMARY : DOCX_BASE64_INDIVIDUAL;

    const docxBlob = Utilities.newBlob(Utilities.base64Decode(b64Data), MimeType.MICROSOFT_WORD, filename + '.docx');
    const tempFileMeta = { title: "TEMP_" + filename, mimeType: MimeType.GOOGLE_DOCS };
    const newDocFile = Drive.Files.insert(tempFileMeta, docxBlob, { convert: true });
    tempDocId = newDocFile.id;

    const doc = DocumentApp.openById(tempDocId);
    const body = doc.getBody();

    // Set to A4 Landscape (841.89 x 595.28 points)
    body.setPageWidth(841.89);
    body.setPageHeight(595.28);
    body.setMarginTop(36);
    body.setMarginBottom(36);
    body.setMarginLeft(54);
    body.setMarginRight(54);

    if (payload.replacements) {
      for (const key in payload.replacements) {
        let value = payload.replacements[key];
        if (value === null || value === undefined) value = "";
        body.replaceText("<<" + key + ">>", String(value));
        body.replaceText("{{" + key + "}}", String(value));
      }
    }

    function processTable(tag, dataArray, replaceFn) {
      const tagResult = body.findText(tag) || body.findText(tag.replace("<<", "{{").replace(">>", "}}"));
      if (tagResult) {
        const element = tagResult.getElement();
        const table = getParentTable_(element);
        if (table && dataArray && dataArray.length > 0) {
          const templateRow = table.getRow(table.getNumRows() - 1);
          for (let i = 0; i < dataArray.length; i++) {
            const newRow = templateRow.copy();
            replaceFn(newRow, dataArray[i], i);
            table.appendTableRow(newRow);
          }
          table.removeRow(table.getNumRows() - 1 - dataArray.length);
        } else if (table) {
          element.asText().setText("ไม่มีข้อมูลเพิ่มเติม");
          const row = getParentTable_(element).getRow(getParentTable_(element).getNumRows() - 1);
          row.replaceText("<<INDEX>>", "-");
          row.replaceText("<<DATE>>", "-");
          row.replaceText("<<STAFF>>", "-");
          row.replaceText("<<IND_EXC>>", "-");
          row.replaceText("<<IND_GOOD>>", "-");
          row.replaceText("<<IND_IMP>>", "-");
          row.replaceText("<<TREND_EXC>>", "-");
          row.replaceText("<<TREND_GOOD>>", "-");
          row.replaceText("<<TREND_IMP>>", "-");
        }
      }
    }

    processTable("<<IND_NAME>>", payload.individuals, (row, item, idx) => {
      row.replaceText("<<IND_NAME>>", String(item.name || "-"));
      row.replaceText("<<IND_EXC>>", String(item.exc || 0));
      row.replaceText("<<IND_GOOD>>", String(item.good || 0));
      row.replaceText("<<IND_IMP>>", String(item.imp || 0));
    });

    processTable("<<TREND_DATE>>", payload.trends, (row, item, idx) => {
      row.replaceText("<<TREND_DATE>>", String(item.date || "-"));
      row.replaceText("<<TREND_EXC>>", String(item.exc || 0));
      row.replaceText("<<TREND_GOOD>>", String(item.good || 0));
      row.replaceText("<<TREND_IMP>>", String(item.imp || 0));
    });

    processTable("<<COMMENT>>", payload.comments, (row, c, idx) => {
      row.replaceText("<<INDEX>>", String(idx + 1));
      row.replaceText("<<COMMENT>>", String(c.text));
      row.replaceText("<<DATE>>", String(c.date || "-"));
      row.replaceText("<<STAFF>>", String(c.staffName || "-"));
    });

    function toggleSection(sectionTag, titleText, isVisible, pageBreakBefore = false) {
      const search = body.findText(sectionTag) || body.findText(sectionTag.replace("<<", "{{").replace(">>", "}}"));
      if (search) {
        const p = search.getElement().getParent();
        if (isVisible) {
          search.getElement().asText().setText(titleText);
          if (pageBreakBefore && p.getParent().getType() === DocumentApp.ElementType.BODY_SECTION) {
            let prev = p.getPreviousSibling();
            while (prev && prev.getType() === DocumentApp.ElementType.PARAGRAPH && prev.asText().getText().trim() === "") {
              let toRemove = prev;
              prev = prev.getPreviousSibling();
              toRemove.removeFromParent();
            }
            p.getParent().insertPageBreak(p.getParent().getChildIndex(p));
          }
        } else {
          let sibling = p.getNextSibling();
          while (sibling) {
            if (sibling.getType() === DocumentApp.ElementType.TABLE) {
              sibling.removeFromParent();
              break;
            }
            sibling = sibling.getNextSibling();
          }
          p.removeFromParent();
        }
      }
    }

    if (type === 'summary') {
      const secs = payload.sections || ["overview", "individuals", "trends", "comments"];
      let count = 1;
      toggleSection("<<SECTION_OVERVIEW>>", secs.includes("overview") ? (count++) + ". ภาพรวมสถิติการประเมิน" : "", secs.includes("overview"));
      toggleSection("<<SECTION_INDIVIDUALS>>", secs.includes("individuals") ? (count++) + ". คะแนนรายบุคคล" : "", secs.includes("individuals"));
      toggleSection("<<SECTION_TRENDS>>", secs.includes("trends") ? (count++) + ". แนวโน้มความพึงพอใจรายวัน" : "", secs.includes("trends"), true);
      toggleSection("<<SECTION_COMMENTS>>", secs.includes("comments") ? (count++) + ". ข้อเสนอแนะเพิ่มเติม" : "", secs.includes("comments"));
    } else if (type === 'individual') {
      const secs = payload.sections || ["overview", "comments"];
      const hasScore = secs.includes("overview") || secs.includes("individuals") || secs.includes("trends");
      let count = 1;
      toggleSection("<<SECTION_IND_SCORE>>", hasScore ? (count++) + ". สรุปคะแนนการประเมิน" : "", hasScore);
      toggleSection("<<SECTION_IND_COMMENTS>>", secs.includes("comments") ? (count++) + ". ข้อเสนอแนะเพิ่มเติม" : "", secs.includes("comments"));
    }
    // Resize tables to fill landscape width proportionally
    try {
      const pWidth = body.getPageWidth() - body.getMarginLeft() - body.getMarginRight();
      const tables = body.getTables();
      for (let i = 0; i < tables.length; i++) {
        const table = tables[i];
        if (table.getNumRows() > 0) {
          const numCols = table.getRow(0).getNumCells();
          if (numCols > 0) {
            let currentTotal = 0;
            let widths = [];
            for (let c = 0; c < numCols; c++) {
              let w = table.getColumnWidth(c);
              if (!w || w <= 0) w = 100;
              widths.push(w);
              currentTotal += w;
            }
            for (let c = 0; c < numCols; c++) {
              let newW = (widths[c] / currentTotal) * pWidth;
              table.setColumnWidth(c, newW);
            }
          }
        }
      }
    } catch (e) { }

    doc.saveAndClose();

    const pdfBlob = DriveApp.getFileById(tempDocId).getAs('application/pdf');
    const base64 = Utilities.base64Encode(pdfBlob.getBytes());

    DriveApp.getFileById(tempDocId).setTrashed(true);

    return { success: true, base64: base64, filename: filename + ".pdf" };
  } catch (err) {
    if (tempDocId) {
      try { DriveApp.getFileById(tempDocId).setTrashed(true); } catch (e) { }
    }
    return { success: false, message: err.toString() };
  }
}
function getParentTable_(element) {
  let parent = element.getParent();
  while (parent) {
    if (parent.getType() === DocumentApp.ElementType.TABLE) {
      return parent;
    }
    parent = parent.getParent();
  }
  return null;
}


